const EDIT_LIMIT = 19500;                      /* правок за одну порцию — у приложения предел 20 000 */
const CANCELLED = {отмена: true};
const settings = {страницы: 'все', куда: REPLACE, вёрстка: EXACT, колонтитулы: true, поля: true, разрывы: false, картинки: true};
const exactOf = opts => opts.куда !== AT_CURSOR && opts.вёрстка !== FLOW;
