const plural = (n, a, b, c) => { const x = Math.abs(n) % 100, y = x % 10; return n + ' ' + (x > 10 && x < 20 ? c : y === 1 ? a : y >= 2 && y <= 4 ? b : c); };
function readPanel(){ const p = параметры({}) || {}; for(const k of Object.keys(settings)) if(p[k] !== undefined) settings[k] = p[k]; return Object.assign({}, settings); }
function Start(){ readPanel(); панель.поле('идёт', false); showSignature(); }
async function guard(f){ try { return await f(); } catch(e){ панель.поле('итог', [{текст: e.message, цвет: RED}]); панель.сообщение(e.message); } }
function pageNumbers(text, total){
const t = String(text || '').trim().toLowerCase().replace(/\s*[-–—]\s*/g, '-');
if(!t || /^(все|всё|all|\*)$/.test(t)) return [...Array(total).keys()];
const out = new Set();
for(const part of t.split(/[,;\s]+/).filter(Boolean)){
let m;
if((m = part.match(/^(\d*)-(\d*)$/)) && (m[1] || m[2])){ const a = m[1] ? +m[1] : 1, b = m[2] ? +m[2] : total; for(let k = Math.max(1, a); k <= Math.min(b, total); k++) out.add(k - 1); }
else if(/^\d+$/.test(part)){ const k = +part; if(k >= 1 && k <= total) out.add(k - 1); }
else throw new Error('Не понял номера страниц «' + text + '». Пишите «все» или, например, «1-3, 5, 7-».');
}
if(!out.size) throw new Error('В этом PDF ' + plural(total, 'страница', 'страницы', 'страниц') + ' — таких номеров в нём нет');
return [...out].sort((a, b) => a - b);
}
const docEmpty = () => документ.блоки.every(b => !String(b.текст || '').trim() && !/<(img|table|hr)\b/i.test(b.html || ''));
async function openDoc(f){
let password = '';
for(let attempt = 0; ; attempt++){
try { return new PDFЯ.Документ(f.байты, {пароль: password}); }
catch(e){
if(!e.нуженПароль) throw e;
const p = await диалог.ввод((attempt ? 'Пароль не подошёл. ' : '') + '«' + f.имя + '» защищён паролем на открытие. Пароль:', '', {пароль: true});
if(p === null || p === '') throw new Error('PDF «' + f.имя + '» защищён паролем на открытие: без пароля его не прочитать.');
password = p;
}
}
}
async function confirmReplace(opts, name){
if(opts.куда !== REPLACE || docEmpty()) return true;
return await диалог.вопрос('В документе есть текст. Заменить его содержимым «' + name + '»? Вернуть прежний текст можно командой «Отменить». Чтобы открыть PDF рядом, создайте новый документ («Файл» → «Новый»).');
}
async function OpenPdf(){ return guard(async () => {
if(typeof ДЕЛА !== 'undefined') панель.поле('дело', 'PDF — документом');
if(job){ панель.сообщение('Идёт разбор «' + job.name + '» — дождитесь его конца или нажмите «Отмена»'); return; }
const files = await файл.выбрать({типы: ['.pdf'], зачем: 'PDF для правки'});
if(!files || !files.length) return;
await openGiven(files[0]);
}); }
async function OpenPdfFile(){ return guard(async () => {
if(typeof ДЕЛА !== 'undefined') панель.поле('дело', 'PDF — документом');
if(job){ панель.сообщение('Идёт разбор «' + job.name + '» — дождитесь его конца или нажмите «Отмена»'); return; }
const f = документ.повод && документ.повод.файл;
if(!f || !f.байты) throw new Error('Приложение не передало файл PDF');
await openGiven(f);
}); }
async function openGiven(f){
const opts = readPanel();
панель.поле('итог', [{текст: 'Читаю «' + f.имя + '»…'}]);
const doc = await openDoc(f);
await doc.потокиОбъектов();
const nodes = doc.страницы();
if(!nodes.length) throw new Error('В PDF не нашлось ни одной страницы');
const numbers = pageNumbers(opts.страницы, nodes.length);
if(!(await confirmReplace(opts, f.имя))){ панель.поле('итог', [{текст: 'Документ не изменён.'}]); return; }
await closeSession(last);                            /* прежний PDF — из ядра: его страницы больше не нужны */
last = {name: f.имя, doc, nodes, numbers, pages: null, session: 0, bytes: f.байты};
lastJob = run(last, opts);
}
async function InsertAgain(){ return guard(async () => {
if(job){ панель.сообщение('Идёт разбор «' + job.name + '» — дождитесь его конца или нажмите «Отмена»'); return; }
if(!last) throw new Error('Сначала откройте PDF: «Открыть PDF…»');
const opts = readPanel(), numbers = pageNumbers(opts.страницы, last.nodes.length);
if(numbers.join() !== last.numbers.join()){ last.numbers = numbers; last.pages = null; await closeSession(last); }
if(!(await confirmReplace(opts, last.name))){ панель.поле('итог', [{текст: 'Документ не изменён.'}]); return; }
lastJob = run(last, opts);
}); }
function Cancel(){
if(!job){ панель.сообщение('Разбор не идёт'); return; }
job.cancel = true;
панель.поле('итог', [{текст: 'Останавливаю разбор «' + job.name + '»…'}]);
}
const core = async (name, data, bytes) => (await ядро.вызвать(name, data, bytes)).данные;
async function closeSession(st){
if(!st || !st.session) return;
const сеанс = st.session; st.session = 0; st.fonts = null;      /* шрифты собираются заново в новом сеансе: там их метрики */
try { await core('pdf.закрыть', {сеанс}); } catch(e){}
}
function placeTables(blocks, tables){
return blocks.map(h => h.replace(/<!--pdf-table:(\d+)-->/g, (m, n) => {
const t = tables[+n];
if(!t) return '';
if(t.html) return t.html;
let x = документ.таблица(t.строки, {шапка: t.шапка});
if(t.стиль) x = x.replace(/^<table\b([^>]*)>/, (m2, attrs) => /\sstyle="/.test(attrs)
? '<table' + attrs.replace(/\sstyle="/, ' style="' + t.стиль + ';') + '>' : '<table' + attrs + ' style="' + t.стиль + '">');
const cell = (t.стиль || '').split(';').filter(s => /^(font-family|font-size):/.test(s.trim())).join(';');
if(cell) x = x.replace(/<(td|th)>/g, '<$1 style="' + cell + '">');
return x;
}));
}
async function imageOf(st, it, кэш){
const pg = st.pages.get(it.страница);
if(!pg) return {skip: 'сбой'};
if(it.вектор){
const key = it.страница + ':' + it.вектор.ид;
if(!кэш.has(key)){
const v = it.вектор;
кэш.set(key, await PDF_IMAGES.convert(st.doc, {vector: {x1: v.x1, y1: v.y1, x2: v.x2, y2: v.y2, paths: v.пути.map(i => pg.пути[i]).filter(Boolean)}}));
}
return кэш.get(key);
}
const src = it.src === null || it.src === undefined ? null : pg.картинки[it.src];
if(!src) return {skip: 'неизвестно'};
let r = await PDF_IMAGES.convert(st.doc, {src, кэш});
if(src.обрезка && r.png && r.pw && r.ph){
try { const c = await PDF_IMAGES.clipped(r, src, {x1: it.x1, y1: it.y, x2: it.x2, y2: it.y2}); if(c) return c; } catch(e){}
}
if(r.png && r.pw && r.ph){
const cx = it.x1 - src.x, cy = it.y - src.y, cw = it.x2 - it.x1, ch = it.y2 - it.y;
if(!(cx <= 0.5 && cy <= 0.5 && src.w - cw <= 0.5 && src.h - ch <= 0.5)){
const sx = r.pw / src.w, sy = r.ph / src.h;
try {
const c = await картинка.преобразовать(r.png, {обрезка: {x: cx * sx, y: cy * sy, ширина: cw * sx, высота: ch * sy}, тип: /^data:image\/jpeg/.test(r.png) ? 'jpeg' : 'png'});
r = {png: c.данные, pw: c.ширина, ph: c.высота};
} catch(e){}
}
}
return r;
}
async function run(st, opts){
const me = {cancel: false, name: st.name};
job = me;
панель.поле('идёт', true); панель.поле('ход', 0);
let shown = 0;
const progress = (share, text) => { const now = Date.now(); if(now - shown < 150) return; shown = now; панель.поле('ход', share); панель.поле('итог', [{текст: text}]); };
const check = () => { if(me.cancel) throw CANCELLED; };
try {
if(!st.pages || !st.session){
await closeSession(st);
st.pages = null;
const сеанс = (await core('pdf.сеанс', null)).сеанс, pages = new Map();
st.session = сеанс;
for(let k = 0; k < st.numbers.length; k++){
check();
progress(0.85 * k / st.numbers.length, 'Разбираю страницу ' + (st.numbers[k] + 1) + ' из ' + st.nodes.length + '…');
let pg;
try { pg = await PDFТ.страница(st.doc, st.nodes[st.numbers[k]], {пути: true}); }
catch(e){ pg = {ш: 595, в: 842, глифы: [], линии: [], картинки: [], ссылки: [], пути: [], сбой: e.message}; }
await core('pdf.страница', {сеанс, номер: st.numbers[k], страница: PDFМОСТ.страница(pg)});
pages.set(st.numbers[k], {ш: pg.ш, в: pg.в, картинки: pg.картинки, пути: pg.пути || []});
pg = null;
await pause();
}
st.pages = pages;
}
check();
const exact = exactOf(opts);
st.exact = exact;
if(opts.шрифты !== false && !st.fonts && typeof документ.шрифты === 'function'){
const sections = await ядро.разделы().catch(() => ({}));
if(+sections.pdf >= 2){
st.fonts = await PDFШ.собрать(st.doc, (имя, данные, байты) => ядро.вызвать(имя, данные, байты), st.session,
async (i, n) => { check(); progress(0.85, 'Шрифты: ' + (i + 1) + ' из ' + n + '…'); if(i % 8 === 7) await pause(); });
} else st.fonts = {начертания: [], пропущено: [], нетЯдра: true};
