check();
const model = await core('pdf.вёрстка', {сеанс: st.session, всего: st.nodes.length, картинки: opts.картинки !== false, точно: exact});
if(model.скан){
панель.поле('итог', [{текст: '«' + st.name + '»: ', жирный: true}, {текст: 'на страницах нет текста — это скан (страницы-картинки). Текст сканов распознаёт раздел «Распознать картинку или снимок» этой панели («Откуда» — «Файл: картинка или скан PDF»). Документ не изменён.', цвет: AMBER}]);
панель.сообщение('В PDF нет текста — это скан: его распознаёт раздел «Распознать картинку или снимок»');
return;
}
if(!model.блоков) throw new Error(model.сбой.length ? 'Страницы не прочитались: ' + model.сбойТекст : 'На выбранных страницах нет ни текста, ни картинок');
const images = model.картинки, done = [], pngs = new Map(), skipped = {}, кэш = new Map();
for(let i = 0; i < images.length; i++){
check();
progress(0.85 + 0.12 * i / images.length, 'Картинки: ' + (i + 1) + ' из ' + images.length + '…');
try { const r = await imageOf(st, images[i], кэш); if(r.png){ done.push({ид: images[i].ид, png: '@' + images[i].ид, pw: r.pw, ph: r.ph}); pngs.set(String(images[i].ид), r.png); } else skipped[r.skip] = (skipped[r.skip] || 0) + 1; }
catch(e){ skipped['сбой'] = (skipped['сбой'] || 0) + 1; }
