}
кэш.clear();
check();
const replace = opts.куда !== AT_CURSOR;
const page = replace ? pageSetup(model, opts, exact) : null;
const out = await core('pdf.разметка', {сеанс: st.session, картинки: done, стили: replace, разрывы: !!opts.разрывы, точно: exact, поля: (page && page.поляPt) || null});
