const blocks = placeTables(out.блоки.map(withImages), out.таблицы);
pngs.clear();
if(!blocks.length) throw new Error('На выбранных страницах нет ни текста, ни картинок');
check();
let fontsPut = null;
if(opts.шрифты !== false && st.fonts && st.fonts.начертания.length && typeof документ.шрифты === 'function'){
progress(0.98, 'Шрифты — в документ…');
try { fontsPut = await документ.шрифты(st.fonts.начертания.map(f => ({семья: f.семья, вес: f.вес, курсив: f.курсив, растяжение: f.растяжение || '', диапазон: f.диапазон, данные: f.данные, имя: f.имя, источник: st.name, знаков: f.знаков}))); }
catch(e){ fontsPut = {ошибка: e && e.message || String(e)}; }
}
progress(0.99, 'Вставляю в документ…');
if(replace){
const old = документ.блоки.length;
if(blocks.length + old + 8 > EDIT_LIMIT) throw new Error('Из PDF выходит ' + plural(blocks.length, 'абзац', 'абзаца', 'абзацев') + ' — больше, чем вставляется за раз. Откройте его частями: в поле «Страницы» — например, «1-100», затем «101-200».');
документ.вставить(0, blocks.join(''));
const n = документ.блоки.length - old;
for(let k = 0; k < old; k++) документ.удалить(n);
if(page.страница) документ.задатьСтраницу(page.страница);
for(const [name, style] of page.стили) документ.задатьСтиль(name, style);
