панель.сообщение('Готово: «' + st.name + '» — ' + plural(blocks.length, 'блок', 'блока', 'блоков') + (replace ? ' в документе' : ' в месте курсора'));
} catch(e){
if(e === CANCELLED){ панель.поле('итог', [{текст: 'Разбор «' + st.name + '» остановлен: документ не изменён.', цвет: AMBER}]); панель.сообщение('Разбор остановлен'); }
