c.h && plural(c.h, 'заголовок', 'заголовка', 'заголовков'), c.list && plural(c.list, 'список', 'списка', 'списков'),
c.table && plural(c.table, 'таблица', 'таблицы', 'таблиц'), c.image && plural(c.image, 'картинка', 'картинки', 'картинок')].filter(Boolean).join(', ') + '.', цвет: GREEN}];
